events.command:
D=$(mktemp -d); cp -r tools "$D/tools"; python3 - "$D" <<PYEOF
import sys
p = sys.argv[1] + "/tools/task-state.mjs"
s = open(p).read()
old = "export const PHASES = [\"intake\", \"planned\", \"executing\", \"verified\", \"adversarial\", \"done\"];"
new = "export const PHASES = [\"intake\", \"planned\", \"executing\", \"verified\", \"adversarial\", \"shipping\", \"done\"];"
assert old in s
open(p, "w").write(s.replace(old, new, 1))
PYEOF
cd "$D" && node --input-type=module -e "
const ws = await import(\"./tools/task-workspace.mjs\");
const st = await import(\"./tools/task-state.mjs\");
const gl = await import(\"./tools/zcode-plugin/lib/gate-law.mjs\");
const rec = { schema: \"stallion/task-state@1\", id: \"t\", riskClass: \"runtime-code\", events: [{ type: \"transition\", to: \"shipping\" }] };
const wsOk = ws.canAddWorkspace(rec, false).ok;
const law = { root: \"/x\", shape: \"stallion\", coverage: { isCodePath: (p) => p.startsWith(\"tools/\"), recordRefusal: () => null, scopeRefusal: (r, f) => r.scope && r.scope[0] && f[0].startsWith(r.scope[0].replace(\"/**\", \"\")) ? null : { reason: \"out\" }, citationRefusal: () => null }, state: { PHASES: st.PHASES, derivePhase: (ev) => ev.at(-1)?.to ?? \"intake\", scopeOf: (r) => r.scope ?? [] } };
const gate = gl.authoringDecision({ filePath: \"/x/tools/a.mjs\", cwd: \"/x\" }, law, [{ ...rec, scope: [\"tools/**\"] }]);
if (!wsOk) { console.error(\"workspace seam did not follow the mutated PHASES\"); process.exit(1); }
if (gate.decision !== \"allow\") { console.error(\"gate seam did not follow the mutated PHASES\"); process.exit(1); }
console.log(\"both seams follow the mutated PHASES\");
"
